<script setup lang="ts">
import {ref,computed,onMounted} from 'vue'
import {onBeforeRouteLeave} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import {get,post,key,date} from '../api'
const communities=ref<any[]>([]),community=ref<number>(),rows=ref<any[]>([]),history=ref<any[]>([]),form=ref<any>(null),baseline=ref(''),busy=ref(false)
const conflict=ref<any>(null)
let attempt:{body:string,key:string}|null=null
async function resolveConflict(){if(!form.value)return;await load();const latest=rows.value.find(r=>r.categoryId===form.value.categoryId);if(!latest)return;conflict.value=latest;try{await ElMessageBox.confirm(`当前服务器人工费 ¥${Number(latest.laborFen)/100}、材料费 ¥${Number(latest.materialFen)/100}，依据：${latest.basis}。保留你的输入并以此最新版本继续编辑？`,'核对版本');form.value.version=latest.version;attempt=null;conflict.value=null}catch{}}
const dirty=computed(()=>form.value&&JSON.stringify(form.value)!==baseline.value)
const historyTotal=(row:any)=>((Number(row.laborFen)+Number(row.materialFen))/100).toFixed(2)
async function discard(){if(busy.value)return false;if(!dirty.value)return true;try{await ElMessageBox.confirm('有未保存的价格修改，是否放弃？','离开编辑');return true}catch{return false}}
onBeforeRouteLeave(discard)
let loadVersion=0
async function load(){if(!community.value)return;const version=++loadVersion;const result=await get('/reference-prices',{communityId:community.value});if(version===loadVersion)rows.value=result}
async function selectCommunity(value:number){if(!await discard())return;community.value=value;form.value=null;conflict.value=null;history.value=[];await load()}
async function edit(row:any){if(!await discard())return;form.value={communityId:community.value,categoryId:row.categoryId,name:row.categoryName,labor:row.laborFen==null?'':String(row.laborFen/100),material:row.materialFen==null?'':String(row.materialFen/100),basis:row.basis||'',enabled:row.enabled==null?true:!!row.enabled,version:row.version??-1};baseline.value=JSON.stringify(form.value);attempt=null;conflict.value=null;history.value=await get('/reference-prices/history',{communityId:community.value,categoryId:row.categoryId})}
async function save(){const f=form.value;if(busy.value||!f)return;if(!/^\d+(\.\d{1,2})?$/.test(f.labor.trim())||!/^\d+(\.\d{1,2})?$/.test(f.material.trim())||!f.basis.trim()){ElMessage.warning('费用必须填写且最多两位小数，免收填0，并填写依据');return}const body={laborFen:Math.round(Number(f.labor)*100),materialFen:Math.round(Number(f.material)*100),basis:f.basis,version:f.version,enabled:f.enabled};if(!Number.isSafeInteger(body.laborFen)||!Number.isSafeInteger(body.materialFen)||body.laborFen<0||body.materialFen<0||body.laborFen+body.materialFen<=0||body.laborFen+body.materialFen>10000000){ElMessage.warning('费用无效');return}const signature=JSON.stringify({communityId:f.communityId,categoryId:f.categoryId,...body});if(attempt?.body!==signature)attempt={body:signature,key:key()};busy.value=true;try{await post(`/reference-prices?communityId=${f.communityId}&categoryId=${f.categoryId}`,body,attempt.key);form.value=null;attempt=null;await load();ElMessage.success('参考价已保存，历史订单价格不变')}catch(e:any){if(e.response?.status===409){conflict.value={};ElMessage.warning('价格已被其他人修改，草稿已保留；请核对最新版本')}}finally{busy.value=false}}
onMounted(async()=>{communities.value=await get('/communities');community.value=communities.value[0]?.id;await load()})
</script>
<template><div class="page-heading"><div><h1>维修参考价</h1><p class="muted">按小区和维修类别维护，自动报价使用当前启用价格。</p></div><el-select :model-value="community" @change="selectCommunity"><el-option v-for="c in communities" :key="c.id" :value="c.id" :label="c.name"/></el-select></div><el-table :data="rows"><el-table-column prop="categoryName" label="维修类别"/><el-table-column label="人工 / 材料（元）"><template #default="{row}">{{row.laborFen==null?'未配置':`${(row.laborFen/100).toFixed(2)} / ${(row.materialFen/100).toFixed(2)}`}}</template></el-table-column><el-table-column label="状态"><template #default="{row}">{{row.version==null?'未配置':row.enabled?'已启用':'已停用'}}</template></el-table-column><el-table-column label="更新时间"><template #default="{row}">{{date(row.updatedAt)}}</template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button @click="edit(row)">维护 / 历史</el-button></template></el-table-column></el-table><section v-if="form" class="panel"><h2>{{form.name}}</h2><el-button v-if="conflict" @click="resolveConflict">核对最新版本并保留草稿</el-button><p>合计 ¥{{((Number(form.labor)||0)+(Number(form.material)||0)).toFixed(2)}}</p><el-form label-position="top" :disabled="busy"><el-form-item label="人工费（元）"><el-input v-model="form.labor"/></el-form-item><el-form-item label="材料费（元，无则填0）"><el-input v-model="form.material"/></el-form-item><el-form-item label="价格依据"><el-input v-model="form.basis" maxlength="450"/></el-form-item><el-switch v-model="form.enabled" active-text="启用自动报价"/><el-button type="primary" :loading="busy" @click="save">保存参考价</el-button></el-form><h3>修改历史</h3><p v-for="h in history" :key="h.id">{{date(h.createdAt)}} · 第{{Number(h.version)+1}}版 · ¥{{historyTotal(h)}} · {{h.enabled?'启用':'停用'}} · 操作人{{h.updatedBy}} · {{h.basis}}</p></section></template>
